import React, { FC } from 'react';
import { SearchOptions } from '../../context/DoctorsContext';

interface FilterFormProps {
  searchOptions: SearchOptions;
  onFilterChange: (filterType: string, value: string | number) => void;
  onSearchChange: (value: string) => void;
}

const FilterForm: FC<FilterFormProps> = ({ searchOptions, onFilterChange, onSearchChange }) => {
  return (
    <form className='filter-form'>

      <label>
        Price:
        <select onChange={(e) => onFilterChange('price', e.target.value)}>
          <option value="">Select a price</option>
          <option value="50">{'< '}50</option>
          <option value="100">{'< '}100</option>
          <option value="200">{'< '}200</option>
          <option value="400">{'< '}400</option>
        </select>
      </label>
      <label>
        Rating:
        <select onChange={(e) => onFilterChange('rating', e.target.value)}>
          <option value="">Select a rating</option>
          <option value="1">1+</option>
          <option value="2">2+</option>
          <option value="3">3+</option>
          <option value="4">4+</option>
        </select>
      </label>
      <label>
        Country:
        <select onChange={(e) => onFilterChange('country', e.target.value)}>
          <option value="">Select a country</option>
          <option value="Ukraine">Ukraine</option>
          <option value="Poland">Poland</option>
          <option value="USA">USA</option>
        </select>
      </label>
      <label>
        Search:
        <label className="input-buttons-menu">
          <input 
            placeholder="Type something..."
            onChange={(e) => onSearchChange(e.target.value)}
            value={searchOptions.term}
          />
        </label>
      </label>
    </form>
  );
};

export default FilterForm;
